using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class PaymentConfiguration : IEntityTypeConfiguration<Payment>
{
    public void Configure(EntityTypeBuilder<Payment> builder)
    {
        //SQL table name
        builder.ToTable("Payments");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //Foreign key configuration, PaymentBatchId is required
        builder.Property(x => x.PaymentBatchId).IsRequired();

        //Amount is required and has a precision of 19,4
        builder.Property(x => x.Amount).HasPrecision(Constants.AmountPrecision, Constants.AmountDecimalPlaces).IsRequired();

        //BeneficiaryName is required and has a maximum length defined
        builder.Property(x => x.BeneficiaryName).IsRequired().HasMaxLength(Constants.MaxNameLength);

        //BeneficiaryAccountIdentifier is required, has a maximum length defined, and is not unicode
        builder.Property(x => x.BeneficiaryAccountIdentifier).IsRequired().HasMaxLength(Constants.MaxAccountIdentifierLength).IsUnicode(false);

        //Reference is required and has a maximum length defined
        builder.Property(x => x.Reference).IsRequired().HasMaxLength(Constants.MaxReferenceLength);

        //Status is required, has a maximum length defined, and is stored as a string in the database
        builder.Property(x => x.Status).HasConversion<string>().HasMaxLength(Constants.MaxStatusLength).IsUnicode(false).IsRequired();

        //BankReference, SettlementReference, and LastStatusReason have maximum lengths defined
        builder.Property(x => x.BankReference).HasMaxLength(Constants.MaxBankReferenceLength);
        builder.Property(x => x.SettlementReference).HasMaxLength(Constants.MaxReferenceLength);
        builder.Property(x => x.LastStatusReason).HasMaxLength(Constants.MaxReasonLength);

        //CreatedAtUtc is not null and is stored as UTC in the database
        builder.Property(x => x.CreatedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //Payment has one PaymentBatch, and PaymentBatch has many Payments
        //The foreign key is PaymentBatchId, and on delete, the behavior is restrict
        builder.HasOne<PaymentBatch>().WithMany().HasForeignKey(x => x.PaymentBatchId).OnDelete(DeleteBehavior.Restrict);
    }
}
